package com.kitchenos.connect.kitchen;

import android.app.Activity;
import android.content.res.ColorStateList;
import android.graphics.Typeface;
import android.graphics.drawable.*;
import android.text.TextUtils;
import android.view.*;
import android.widget.*;
import com.kitchenos.common.*;

/** Component geometry from Kalomatik UI Kit: open rows, centred brand and compact meal entries. */
public final class KitViews {
    public static TextView text(Activity a,String value,int size,int color,boolean bold){TextView t=Ui.text(a,value,size);t.setTextColor(color);t.setPadding(0,0,0,0);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
    public static GradientDrawable shape(Activity a,int color,int radius,int border){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(Ui.dp(a,radius));if(border!=0)d.setStroke(Ui.dp(a,1),border);return d;}
    public static Button icon(Activity a,String glyph,String label,Runnable action){Button b=new Button(a);b.setStateListAnimator(null);b.setElevation(0);b.setMinWidth(0);b.setMinimumWidth(0);b.setMinHeight(0);b.setMinimumHeight(0);b.setPadding(0,0,0,0);b.setAllCaps(false);b.setText(glyph);b.setTextSize(25);b.setTextColor(Ui.INK);b.setContentDescription(label);b.setBackground(new RippleDrawable(ColorStateList.valueOf(0x22ee6542),shape(a,0,22,0),null));b.setOnClickListener(v->action.run());return b;}
    public static ImageButton imageIcon(Activity a,String asset,String label,Runnable action){ImageButton b=new ImageButton(a);b.setImageResource(a.getResources().getIdentifier(asset,"drawable",a.getPackageName()));if(asset.equals("ic_more"))b.setImageTintList(ColorStateList.valueOf(Ui.INK));b.setScaleType(ImageView.ScaleType.FIT_CENTER);b.setPadding(Ui.dp(a,11),Ui.dp(a,11),Ui.dp(a,11),Ui.dp(a,11));b.setContentDescription(label);b.setBackground(new RippleDrawable(ColorStateList.valueOf(0x22ee6542),shape(a,0,22,0),null));b.setOnClickListener(v->action.run());return b;}
    public static void divider(Activity a,LinearLayout parent){View line=new View(a);line.setBackgroundColor(Ui.LINE);parent.addView(line,new LinearLayout.LayoutParams(-1,Ui.dp(a,1)));}
    public static void space(Activity a,LinearLayout parent,int height){parent.addView(new View(a),new LinearLayout.LayoutParams(1,Ui.dp(a,height)));}
    public static void brand(Activity a,LinearLayout parent,Runnable menu){FrameLayout top=new FrameLayout(a);parent.addView(top,new LinearLayout.LayoutParams(-1,Ui.dp(a,44)));LinearLayout word=new LinearLayout(a);word.setGravity(Gravity.CENTER_VERTICAL);ImageView plate=new ImageView(a);plate.setImageDrawable(new PlateDrawable());LinearLayout.LayoutParams image=new LinearLayout.LayoutParams(Ui.dp(a,32),Ui.dp(a,32));image.rightMargin=Ui.dp(a,8);word.addView(plate,image);TextView title=text(a,"Kalomatik",23,Ui.INK,true);title.setLetterSpacing(-.07f);word.addView(title);top.addView(word,new FrameLayout.LayoutParams(-2,-1,Gravity.CENTER));top.addView(imageIcon(a,"ic_more","Menü öffnen",menu),new FrameLayout.LayoutParams(Ui.dp(a,44),-1,Gravity.RIGHT));}
    public static void heading(Activity a,LinearLayout parent,String title,String link,Runnable action){LinearLayout line=new LinearLayout(a);line.setGravity(Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=Ui.dp(a,20);lp.bottomMargin=Ui.dp(a,12);parent.addView(line,lp);TextView h=text(a,title,27,Ui.INK,true);h.setLetterSpacing(-.035f);line.addView(h,new LinearLayout.LayoutParams(0,-2,1));if(link!=null){TextView more=text(a,link,19,Ui.MUTED,false);more.setPaintFlags(more.getPaintFlags()|android.graphics.Paint.UNDERLINE_TEXT_FLAG);more.setMinHeight(Ui.dp(a,44));more.setGravity(Gravity.CENTER_VERTICAL);more.setOnClickListener(v->action.run());line.addView(more);}}
    public static LinearLayout row(Activity a,LinearLayout parent,String title,String subtitle,String end,Runnable click){LinearLayout line=new LinearLayout(a);line.setGravity(Gravity.CENTER_VERTICAL);line.setPadding(0,Ui.dp(a,12),0,Ui.dp(a,12));line.setMinimumHeight(Ui.dp(a,62));line.setBackground(new RippleDrawable(ColorStateList.valueOf(0x15ee6542),shape(a,0,12,0),null));LinearLayout copy=Ui.column(a);copy.addView(text(a,title,23,Ui.INK,true));if(subtitle!=null&&!subtitle.isEmpty()){TextView meta=text(a,subtitle,18,Ui.MUTED,false);meta.setPadding(0,Ui.dp(a,5),0,0);copy.addView(meta);}line.addView(copy,new LinearLayout.LayoutParams(0,-2,1));TextView arrow=text(a,end==null?"›":end,19,Ui.ACCENT,false);arrow.setGravity(Gravity.CENTER);line.addView(arrow,new LinearLayout.LayoutParams(Ui.dp(a,end==null?32:74),-2));if(click!=null){line.setOnClickListener(v->click.run());line.setContentDescription(title);}parent.addView(line,new LinearLayout.LayoutParams(-1,-2));divider(a,parent);return line;}
    public static LinearLayout meal(Activity a,LinearLayout parent,Recipe recipe,String context,Runnable open){LinearLayout row=new LinearLayout(a);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(Ui.dp(a,12),Ui.dp(a,10),Ui.dp(a,8),Ui.dp(a,10));row.setBackground(new RippleDrawable(ColorStateList.valueOf(0x18ee6542),shape(a,a instanceof KitchenChatActivity?Ui.CARD:Ui.BG,24,0),null));LinearLayout.LayoutParams outer=new LinearLayout.LayoutParams(-1,-2);outer.bottomMargin=Ui.dp(a,10);parent.addView(row,outer);ImageView image=new ImageView(a);image.setImageResource(a.getResources().getIdentifier("meal_placeholder","drawable",a.getPackageName()));image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setClipToOutline(true);image.setBackground(shape(a,Ui.LINE,16,0));LinearLayout.LayoutParams photo=new LinearLayout.LayoutParams(Ui.dp(a,112),Ui.dp(a,100));photo.rightMargin=Ui.dp(a,12);row.addView(image,photo);if(recipe.source.matches("https://app\\.kalomatik\\.ai/api/recipes/[a-f0-9]{64}"))com.kitchenos.connect.ui.FoodImages.load(image,recipe.source+"/cover");LinearLayout copy=Ui.column(a);TextView title=text(a,recipe.title,23,Ui.INK,true);title.setMaxLines(2);title.setEllipsize(TextUtils.TruncateAt.END);copy.addView(title);TextView meta=text(a,recipe.ingredients.length()+" Zutaten"+(recipe.servings>0?" · "+recipe.servings+" Portionen":""),18,Ui.MUTED,false);meta.setPadding(0,Ui.dp(a,4),0,0);copy.addView(meta);if(context!=null&&!context.isEmpty()){TextView note=text(a,context,18,Ui.MUTED,false);note.setPadding(0,Ui.dp(a,5),0,0);copy.addView(note);}row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));Button arrow=icon(a,"›","Rezept öffnen",open);arrow.setTextColor(Ui.ACCENT);row.addView(arrow,new LinearLayout.LayoutParams(Ui.dp(a,32),Ui.dp(a,48)));row.setOnClickListener(v->open.run());row.setContentDescription("Rezept: "+recipe.title);return row;}
}
